      "tipo": "DrawCalls",
      "causa_raiz": "Excesso crítico de Draw Calls (pico de 20.492 contra o orçamento de 2.579), resultando em saturação do pipeline gráfico e estourando o tempo de GPU em até 43.89 ms (teto de 16.7 ms). Isso ocorre pela renderização individual de múltiplos objetos sem GPU Instancing, ausência de Static Batching e multiplicação de instâncias de materiais únicos.",
      "codigo_refatorado": "using UnityEngine;

public class InstancedRendererBatch : MonoBehaviour
{
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material targetMaterial;
    [SerializeField] private Transform[] sourceObjects;

    private Matrix4x4[][] batches;
    private MaterialPropertyBlock propertyBlock;
    private const int BATCH_SIZE = 1023;

    private void Awake()
    {
        if (targetMesh == null || targetMaterial == null || sourceObjects == null || sourceObjects.Length == 0)
            return;

        targetMaterial.enableInstancing = true;
        propertyBlock = new MaterialPropertyBlock();

        int totalObjects = sourceObjects.Length;
        int batchCount = Mathf.CeilToInt((float)totalObjects / BATCH_SIZE);
        batches = new Matrix4x4[batchCount][];

        for (int b = 0; b < batchCount; b++)
        {
            int currentSize = Mathf.Min(BATCH_SIZE, totalObjects - (b * BATCH_SIZE));
            batches[b] = new Matrix4x4[currentSize];
            for (int i = 0; i < currentSize; i++)
            {
                int objIndex = b * BATCH_SIZE + i;
                batches[b][i] = sourceObjects[objIndex].localToWorldMatrix;
                sourceObjects[objIndex].gameObject.SetActive(false);
            }
        }
    }

    private void Update()
    {
        if (batches == null || targetMesh == null || targetMaterial == null) return;

        for (int i = 0; i < batches.Length; i++)
        {
            Graphics.DrawMeshInstanced(
                targetMesh,
                0,
                targetMaterial,
                batches[i],
                batches[i].Length,
                propertyBlock,
                UnityEngine.Rendering.ShadowCastingMode.On,
                true
            );
        }
    }
}",
      "explicacao_didatica": "Imagine que cada Draw Call é um garçom indo à cozinha levar um único prato por vez; 20.492 viagens deixam a cozinha travada. Com o código de GPU Instancing, o garçom coloca até 1.023 pratos em uma bandeja e faz apenas uma viagem, reduzindo drasticamente as requisições enviadas à placa de vídeo e estabilizando a taxa de quadros em 60 FPS."
    }
  ],
  "dicas_level_design": "1. Ativação de Batching Estático: Marque todos os objetos do cenário que não se movem (paredes, prédios, mobília) como 'Batching Static' no Inspector para que a Unity combine suas malhas automaticamente.
2. Atlas de Texturas: Combine texturas de pequenos objetos decorativos (props, caixas, postes) em um único Atlas de Texturas, permitindo o compartilhamento de um único Material.
3. Occlusion Culling: Configure e asse (Bake) o Occlusion Culling para impedir que a GPU processe objetos escondidos atrás de paredes ou montanhas fora do campo de visão.
4. Sistema de LODs e Culling por Distância: Implemente LOD Groups agressivos para cenários distantes e reduza a distância de desenho (Layer Cull Distances) para objetos pequenos de folhagem e detritos."
}

